effects.needle:
async readRetiredCodes(organizationId: string): Promise<readonly string[] | null> {
  const owner = readCatalogueId(organizationId, 'retired codes organization');
  return await this.execute('read', (db) => {
    if (!this.organizationExists(db, owner)) return null;
    const retirements = captureStepRetirementsIn(db, owner);
    this.bindingRows(db, owner);
    return db
      .all<{ id: unknown; code: unknown }>(
        sql`SELECT id,code FROM step_definition WHERE organization_id=${owner}`,
      )
      .filter((row) => retirements.has(readCatalogueId(row.id, 'retired definition identity')))
      .map((row) => readCatalogueId(row.code, 'retired step code'))
      .sort();
  });
}

